const S3_KEY = 'apk/ivx-holdings-1.10.8-owner.apk';

function getSignatureKey(key, dateStamp, region, service) {
  const kDate = createHmac('sha256', 'AWS4' + key).update(dateStamp).digest();
  const kRegion = createHmac('sha256', kDate).update(region).digest();
  const kService = createHmac('sha256', kRegion).update(service).digest();
  const kSigning = createHmac('sha256', kService).update('aws4_request').digest();
  return kSigning;
}

async function upload() {
  const fileData = readFileSync(APK_PATH);
  const fileSize = statSync(APK_PATH).size;
  console.log(`File size: ${(fileSize / (1024 * 1024)).toFixed(1)} MB`);

  const now = new Date();
  const iso = now.toISOString();
  const amzDate = iso.replace(/[:.-]/g, '').replace(/\d{3}Z$/, 'Z');
  const dateStamp = amzDate.substring(0, 8);

  // Virtual-hosted style: bucket.s3.region.amazonaws.com
  const host = `${BUCKET}.s3.${REGION}.amazonaws.com`;
  const url = `https://${host}/${S3_KEY}`;

  const payloadHash = createHash('sha256').update(fileData).digest('hex');
  const canonicalHeaders = `host:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${amzDate}\n`;
  const signedHeaders = 'host;x-amz-content-sha256;x-amz-date';

  const canonicalRequest = [
    'PUT',
    `/${S3_KEY}`,
    '',
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join('\n');

  const canonicalHash = createHash('sha256').update(canonicalRequest).digest('hex');
  const credentialScope = `${dateStamp}/${REGION}/s3/aws4_request`;
  const stringToSign = [
    'AWS4-HMAC-SHA256',
    amzDate,
    credentialScope,
    canonicalHash,
  ].join('\n');

  const signingKey = getSignatureKey(SECRET_KEY, dateStamp, REGION, 's3');
  const signature = createHmac('sha256', signingKey).update(stringToSign).digest('hex');
  const authorization = `AWS4-HMAC-SHA256 Credential=${ACCESS_KEY}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

  console.log('Uploading to:', url);
  const response = await fetch(url, {
    method: 'PUT',
    headers: {
      'Authorization': authorization,
      'x-amz-date': amzDate,
      'x-amz-content-sha256': payloadHash,
      'Content-Type': 'application/vnd.android.package-archive',
      'Content-Disposition': 'attachment; filename="ivx-holdings-1.10.8-owner.apk"',
      'Cache-Control': 'no-cache, no-store, must-revalidate',
    },
    body: fileData,
  });

  if (response.ok) {
    console.log('SUCCESS! Status:', response.status);
    console.log('ETag:', response.headers.get('etag'));
    console.log('Download URL: https://ivxholding.com/' + S3_KEY);
  } else {
    const body = await response.text();
    console.error('FAILED! Status:', response.status);
    console.error('Response:', body.substring(0, 500));
  }
}

